import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJFGRv8Z.js";var i=JSON.parse(`{"title":"套餐、钱包与订单","description":"","frontmatter":{},"headers":[],"relativePath":"guide/plans-billing.md","filePath":"guide/plans-billing.md","lastUpdated":1788621106000}`),a={name:`guide/plans-billing.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="套餐、钱包与订单" tabindex="-1">套餐、钱包与订单 <a class="header-anchor" href="#套餐、钱包与订单" aria-label="Permalink to “套餐、钱包与订单”">​</a></h1><h2 id="套餐" tabindex="-1">套餐 <a class="header-anchor" href="#套餐" aria-label="Permalink to “套餐”">​</a></h2><p>平台可提供免费、个人和企业套餐。每档套餐的邮箱数量、存储、发信额度、企业功能和计费周期由管理员配置，因此文档不固定写死价格。</p><p>升级前在套餐页核对：适用对象、计费周期、自动续费状态、当前配额和到期后的处理方式。</p><h2 id="钱包" tabindex="-1">钱包 <a class="header-anchor" href="#钱包" aria-label="Permalink to “钱包”">​</a></h2><p>钱包以页面标明的币种显示余额。充值成功后会生成交易流水；余额支付则同时生成订单和扣款记录。不要仅凭浏览器跳转结果判断到账，应以钱包流水和订单状态为准。</p><h2 id="订单状态" tabindex="-1">订单状态 <a class="header-anchor" href="#订单状态" aria-label="Permalink to “订单状态”">​</a></h2><table tabindex="0"><thead><tr><th>状态</th><th>说明</th></tr></thead><tbody><tr><td>待支付</td><td>订单已创建，尚未收到有效支付结果</td></tr><tr><td>已支付</td><td>支付回调已验证，权益应开始生效</td></tr><tr><td>已取消/已关闭</td><td>订单不再接受支付</td></tr><tr><td>退款中/已退款</td><td>按平台支持情况处理，查看流水或联系管理员</td></tr></tbody></table><p>支付页面关闭、网络中断或重复跳转时，先刷新订单状态。仍未更新再提交工单，并提供订单号；不要提供银行卡密码、支付密码或完整密钥。</p><h2 id="兑换码" tabindex="-1">兑换码 <a class="header-anchor" href="#兑换码" aria-label="Permalink to “兑换码”">​</a></h2><p>兑换码可能增加余额、套餐时长或特定权益，具体以兑换结果为准。每个兑换码有适用范围、有效期和使用次数限制。</p><h2 id="订阅管理" tabindex="-1">订阅管理 <a class="header-anchor" href="#订阅管理" aria-label="Permalink to “订阅管理”">​</a></h2><p>取消订阅前查看权益终止时间。若系统支持恢复，可在当前周期结束前恢复。组织套餐由组织所有者或有权管理员管理，个人套餐由账号本人管理。</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};